import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

// Layout Components
import Header from './components/Header';
import Navbar from './components/Navbar';
import Footer from './components/Footer';

// Pages
import Home from './Pages/Home';
import About from './Pages/About';
import Contact from './Pages/contact';
import Courses from './Pages/Courses';
import WorkshopsScreen from './Pages/WorkshopsScreen';
import InternshipsScreen from './Pages/InternshipsScreen';
import ProjectsScreen from './Pages/ProjectsScreen';

import MyCoursesScreen from './Pages/MyCoursesScreen';
import CareerGuidanceScreen from './Pages/CareerGuidanceScreen';

export default function App() {
  return (
    <Router>
      {/* 
        The main wrapper enforces the deep black theme across the entire app. 
        Light mode has been completely removed.
      */}
      <div className="min-h-screen bg-[#000000] text-[#EAEFF8] flex flex-col font-sans selection:bg-[#00D4FF] selection:text-[#000000]">
        
        {/* Persistent Layout Elements */}
        <Header />
        <Navbar />

        {/* Dynamic Page Routing */}
        <main className="flex-1 relative z-10">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/dashboard" element={<StudentDashboardScreen />} />
            <Route path="/guidance" element={<CareerGuidanceScreen />} />
            <Route path="/workshops" element={<WorkshopsScreen />} />
            <Route path="/courses" element={<Courses />} />
            <Route path="/my-courses" element={<MyCoursesScreen />} />
            <Route path="/internships" element={<InternshipsScreen />} />
            
            {/* Project Routes for B.Tech and M.Tech */}
            <Route path="/btech-projects" element={<ProjectsScreen type="B.Tech" />} />
            <Route path="/mtech-projects" element={<ProjectsScreen type="M.Tech" />} />
            
            <Route path="/about" element={<About />} />
            <Route path="/contact" element={<Contact />} />
          </Routes>
        </main>

        {/* Persistent Footer */}
        <Footer />
      </div>
    </Router>
  );
}
